#include <algorithm>
#include <cmath>

class Solution {
public:
    long long minimumMaxValue(int n, int index, int value) {
        long long steps = n - 1 - index;
        if (value % 2 == 0) return (long long)value + steps * 2;
        int p = value;
        for (int d = 2; d * d <= value; ++d) {
            if (value % d == 0) { p = d; break; }
        }
        return (long long)value + steps * std::max(2, p);
    }
};

class Solution {
    public long minimumMaxValue(int n, int index, int value) {
        long steps = n - 1 - index;
        if (value % 2 == 0) return (long) value + steps * 2;
        int p = value;
        for (int d = 2; (long) d * d <= value; d++) {
            if (value % d == 0) { p = d; break; }
        }
        return (long) value + steps * Math.max(2, p);
    }
}

var minimumMaxValue = function(n, index, value) {
    const steps = n - 1 - index;
    if (value % 2 === 0) return value + steps * 2;
    let p = value;
    for (let d = 2; d * d <= value; d++) {
        if (value % d === 0) { p = d; break; }
    }
